function PasswordInput({ value, onChange }) {
  return (
    <Toggle render={({ on, toggle }) => (
      <div>
        <input
          data-testid="password-input"
          type={on ? 'text' : 'password'}
          value={value}
          onChange={onChange}
        />
        <button data-testid="toggle-btn" onClick={toggle}>
          {on ? 'Hide' : 'Show'}
        </button>
      </div>
    )} />
  );
}

const BadgedButton = withBadge(
